Graphics._createVideo = function() {
    this._video = document.createElement('video');
    this._video.id = 'GameVideo';
    this._video.style.opacity = 0;
    this._video.setAttribute('playsinline', '');
    this._video.setAttribute('x5-video-player-fullscreen',true);
    this._video.setAttribute('x5-video-player-type','h5');
    this._video.setAttribute('x5-video-orientation', 'landscape');

    this._video.volume = this._videoVolume || 1;
    this._video.addEventListener("x5videoenterfullscreen", function(){
    })
    this._video.addEventListener("x5videoexitfullscreen", function(){
      Graphics._onVideoEnd();
    })
    this._updateVideo();
    document.body.appendChild(this._video);
};
